{"filePath":"/Users/dk/lab-data/ai-suite/.opencode/plugins/opencode-logger.ts","content":"import type { Plugin } from "@opencode-ai/plugin"

const LOG_DIR = ".opencode/logs"

function formatTimestamp(): string {
  return new Date().toISOString()
}

function safeStringify(obj: unknown): string {
  try {
    return JSON.stringify(obj)
  } catch {
    return JSON.stringify({ error: "failed to serialize" })
  }
}

function writeLog(path: string, entry: Record<string, unknown>) {
  try {
    const dir = path.substring(0, path.lastIndexOf("/"))
    Bun.spawnSync(["mkdir", "-p", dir])
    Bun.spawnSync(["tee", "-a", path], {
      stdin: new TextEncoder().encode(safeStringify(entry) + "\n"),
      stdout: "ignore",
      stderr: "ignore",
    })
  } catch {
    // Plugin failures must not crash OpenCode
  }
}

function writeLogSync(path: string, entry: Record<string, unknown>) {
  try {
    const dir = path.substring(0, path.lastIndexOf("/"))
    Bun.spawnSync(["mkdir", "-p", dir])
    Bun.spawnSync(["tee", "-a", path], {
      stdin: new TextEncoder().encode(safeStringify(entry) + "\n"),
      stdout: "ignore",
      stderr: "ignore",
    })
  } catch {
    // Plugin failures must not crash OpenCode
  }
}

interface PartRecord {
  timestamp: string
  type: string
  text?: string
  data?: string
  toolCallID?: string
  toolName?: string
  args?: string
}

interface MessageRecord {
  id: string
  sessionID: string | null
  role: string
  modelID: string | null
  parts: PartRecord[]
  timestamp: string
}

interface SessionState {
  id: string
  model: string | null
  created: string
  messages: Map<string, MessageRecord>
}

const sessions = new Map<string, SessionState>()
let currentSessionID: string | null = null

function logPath(sessionID: string): string {
  return `${LOG_DIR}/${sessionID}.jsonl`
}

function ensureSession(sessionID: string): SessionState {
  let s = sessions.get(sessionID)
  if (!s) {
    s = { id: sessionID, model: null, created: formatTimestamp(), messages: new Map() }
    sessions.set(sessionID, s)
    const entry = {
      timestamp: s.created,
      sessionID,
      type: "session.created",
      payload: { sessionID },
    }
    writeLog(logPath(sessionID), entry)
  }
  return s
}

function ensureMessage(session: SessionState, msgID: string, role: string, sessionID: string | null, modelID: string | null): MessageRecord {
  let m = session.messages.get(msgID)
  if (!m) {
    m = { id: msgID, sessionID, role, modelID, parts: [], timestamp: formatTimestamp() }
    session.messages.set(msgID, m)
  }
  if (modelID) m.modelID = modelID
  return m
}

export const OpenCodeLogger: Plugin = async ({ directory }) => {
  return {
    event: async ({ event }) => {
      try {
        const props = (event as any).properties
        switch (event.type) {
          case "session.created": {
            const info = props?.info
            if (!info?.id) break
            currentSessionID = info.id
            const s = ensureSession(info.id)
            s.model = info.modelID ?? info.model ?? null
            break
          }

          case "message.part.updated": {
            const part = props?.part
            if (!part?.messageID) break

            const msgProps = props?.message
            const role = msgProps?.role ?? part.role ?? "unknown"
            const msgSessionID = msgProps?.sessionID ?? currentSessionID
            const modelID = msgProps?.modelID ?? null

            if (!msgSessionID) break

            const s = ensureSession(msgSessionID)
            if (modelID) s.model = modelID

            const msg = ensureMessage(s, part.messageID, role, msgSessionID, modelID)

            const record: PartRecord = {
              timestamp: formatTimestamp(),
              type: part.type,
            }

            switch (part.type) {
              case "text": {
                record.text = part.text ?? ""
                break
              }
              case "reasoning": {
                record.text = part.text ?? part.reasoning ?? ""
                break
              }
              case "tool_call": {
                record.toolCallID = part.toolCallID ?? ""
                record.toolName = part.toolName ?? ""
                record.args = part.args ?? ""
                record.data = part.data ?? ""
                break
              }
              case "tool_result": {
                record.toolCallID = part.toolCallID ?? ""
                record.data = part.data ?? part.text ?? ""
                break
              }
              default: {
                record.text = part.text ?? ""
              }
            }

            msg.parts.push(record)

            const logPayload: Record<string, unknown> = {
              messageID: part.messageID,
              role,
              partType: part.type,
              modelID,
            }

            if (part.type === "text") {
              logPayload.text = part.text
            } else if (part.type === "reasoning") {
              logPayload.reasoning = part.text ?? part.reasoning
            } else if (part.type === "tool_call") {
              logPayload.toolCallID = part.toolCallID
              logPayload.toolName = part.toolName
              logPayload.args = part.args
            } else if (part.type === "tool_result") {
              logPayload.toolCallID = part.toolCallID
              logPayload.data = part.data ?? part.text
            }

            writeLog(logPath(msgSessionID), {
              timestamp: record.timestamp,
              sessionID: msgSessionID,
              type: "message.part",
              payload: logPayload,
            })
            break
          }

          case "message.updated": {
            const info = props?.info
            if (!info?.id) break
            const msgSessionID = info.sessionID ?? currentSessionID
            if (!msgSessionID) break
            const s = ensureSession(msgSessionID)
            const msg = ensureMessage(s, info.id, info.role, msgSessionID, info.modelID ?? null)
            if (info.modelID) s.model = info.modelID
            break
          }

          case "session.status": {
            const statusProps = props?.properties ?? props
            if (statusProps?.status?.type !== "idle") break
            const sessionID = statusProps?.sessionID ?? currentSessionID
            if (!sessionID) break

            const s = sessions.get(sessionID)
            if (!s) break

            const allParts: Record<string, unknown>[] = []
            for (const msg of s.messages.values()) {
              for (const p of msg.parts) {
                allParts.push({
                  messageID: msg.id,
                  role: msg.role,
                  modelID: msg.modelID,
                  ...p,
                })
              }
            }

            writeLog(logPath(sessionID), {
              timestamp: formatTimestamp(),
              sessionID,
              type: "turn.complete",
              payload: {
                model: s.model,
                messageCount: s.messages.size,
                partCount: allParts.length,
              },
            })
            break
          }

          case "session.compacted": {
            const sessionID = props?.sessionID ?? currentSessionID
            if (!sessionID) break
            writeLog(logPath(sessionID), {
              timestamp: formatTimestamp(),
              sessionID,
              type: "session.compacted",
              payload: {},
            })
            break
          }

          case "session.deleted": {
            const info = props?.info
            const sessionID = info?.id ?? currentSessionID
            if (!sessionID) break
            writeLogSync(logPath(sessionID), {
              timestamp: formatTimestamp(),
              sessionID,
              type: "session.deleted",
              payload: {},
            })
            sessions.delete(sessionID)
            if (currentSessionID === sessionID) currentSessionID = null
            break
          }

          case "server.instance.disposed": {
            if (!currentSessionID) break
            writeLogSync(logPath(currentSessionID), {
              timestamp: formatTimestamp(),
              sessionID: currentSessionID,
              type: "server.shutdown",
              payload: {},
            })
            sessions.delete(currentSessionID)
            currentSessionID = null
            break
          }
        }
      } catch {
        // Silently ignore — plugin failures must not crash OpenCode
      }
    },
  }
}
"}

{"content":"import type { Plugin } from "@opencode-ai/plugin"
import { mkdirSync, appendFileSync } from "node:fs"
import { join } from "node:path"

const LOG_BASE = ".opencode/logs"

function ts(): string {
  return new Date().toISOString()
}

function j(o: unknown): string {
  try {
    return JSON.stringify(o)
  } catch {
    return JSON.stringify({ error: "serialize failed" })
  }
}

function write(sessionID: string, entry: Record<string, unknown>) {
  try {
    const dir = join(LOG_BASE)
    mkdirSync(dir, { recursive: true })
    appendFileSync(join(dir, `${sessionID}.jsonl`), j(entry) + "\n")
  } catch {
    // Plugin failures must not crash OpenCode
  }
}

interface LogMsg {
  id: string
  role: string
  sessionID: string | null
  modelID: string | null
  parts: LogPart[]
}

interface LogPart {
  ts: string
  type: string
  text?: string
  toolCallID?: string
  toolName?: string
  args?: string
  data?: string
}

let currentSessionID: string | null = null
const msgStore = new Map<string, LogMsg>()

function ensureMsg(id: string, role: string, sessionID: string | null, modelID: string | null): LogMsg {
  let m = msgStore.get(id)
  if (!m) {
    m = { id, role, sessionID, modelID, parts: [] }
    msgStore.set(id, m)
  }
  if (modelID) m.modelID = modelID
  if (role !== "unknown") m.role = role
  return m
}

export const OpenCodeLogger: Plugin = async () => {
  return {
    event: async ({ event }) => {
      try {
        const p = (event as any).properties
        switch (event.type) {
          case "session.created": {
            const info = p?.info
            if (!info?.id) break
            currentSessionID = info.id
            write(info.id, {
              timestamp: ts(),
              sessionID: info.id,
              type: "session.created",
              model: info.modelID ?? info.model ?? null,
            })
            break
          }

          case "message.updated": {
            const info = p?.info
            if (!info?.id) break
            ensureMsg(info.id, info.role, info.sessionID ?? currentSessionID, info.modelID ?? null)
            break
          }

          case "message.part.updated": {
            const part = p?.part
            if (!part?.messageID) break

            const msgProps = p?.message
            const role = msgProps?.role ?? "unknown"
            const sessionID = msgProps?.sessionID ?? currentSessionID
            if (!sessionID) break

            const msg = ensureMsg(part.messageID, role, sessionID, msgProps?.modelID ?? null)

            const entry: Record<string, unknown> = {
              timestamp: ts(),
              sessionID,
              type: "message.part",
              role: msg.role,
              partType: part.type,
              modelID: msg.modelID,
              messageID: part.messageID,
            }

            switch (part.type) {
              case "text":
                entry.text = part.text ?? ""
                break
              case "reasoning":
                entry.reasoning = part.text ?? part.reasoning ?? ""
                break
              case "tool_call":
                entry.toolCallID = part.toolCallID ?? ""
                entry.toolName = part.toolName ?? ""
                entry.args = part.args ?? ""
                break
              case "tool_result":
                entry.toolCallID = part.toolCallID ?? ""
                entry.result = part.data ?? part.text ?? ""
                break
              default:
                entry.text = part.text ?? ""
            }

            msg.parts.push({
              ts: ts(),
              type: part.type,
              ...(part.type === "text" ? { text: part.text } : {}),
              ...(part.type === "reasoning" ? { text: part.text ?? part.reasoning } : {}),
              ...(part.type === "tool_call" ? { toolCallID: part.toolCallID, toolName: part.toolName, args: part.args } : {}),
              ...(part.type === "tool_result" ? { toolCallID: part.toolCallID, data: part.data ?? part.text } : {}),
            })

            write(sessionID, entry)
            break
          }

          case "session.status": {
            const sp = p?.properties ?? p
            if (sp?.status?.type !== "idle") break
            const sid = sp?.sessionID ?? currentSessionID
            if (!sid) break

            const model = msgStore.values().next().value?.modelID ?? null
            write(sid, {
              timestamp: ts(),
              sessionID: sid,
              type: "turn.complete",
              model,
              messagesBuffered: msgStore.size,
            })
            break
          }

          case "session.compacted": {
            const sid = p?.sessionID ?? currentSessionID
            if (!sid) break
            write(sid, {
              timestamp: ts(),
              sessionID: sid,
              type: "session.compacted",
            })
            break
          }

          case "session.deleted": {
            const info = p?.info
            const sid = info?.id ?? currentSessionID
            if (!sid) break
            write(sid, {
              timestamp: ts(),
              sessionID: sid,
              type: "session.deleted",
            })
            msgStore.clear()
            if (currentSessionID === sid) currentSessionID = null
            break
          }

          case "server.instance.disposed": {
            if (!currentSessionID) break
            write(currentSessionID, {
              timestamp: ts(),
              sessionID: currentSessionID,
              type: "server.shutdown",
            })
            msgStore.clear()
            currentSessionID = null
            break
          }
        }
      } catch {
        // Plugin failures must not crash OpenCode
      }
    },
  }
}
