import { mkdirSync, appendFileSync, writeFileSync } from "node:fs"
import { join } from "node:path"

const LOG_BASE = ".opencode/logs"

function ts(): string {
  return new Date().toISOString()
}

function json(o: unknown): string {
  try {
    return JSON.stringify(o)
  } catch {
    return JSON.stringify({ error: "serialize failed" })
  }
}

function writeJSONL(sessionID: string, entry: Record<string, unknown>) {
  try {
    mkdirSync(LOG_BASE, { recursive: true })
    appendFileSync(join(LOG_BASE, `${sessionID}.jsonl`), json(entry) + "\n")
  } catch {
    // Plugin failures must not crash OpenCode
  }
}

// ---------------------------------------------------------------------------
// YAML helpers
// ---------------------------------------------------------------------------

function yamlVal(v: unknown, indent: number): string {
  const pad = "  ".repeat(indent)
  if (v === null || v === undefined) return `${pad}null`
  if (typeof v === "string") {
    if (v.includes("\n") || v.includes('"') || v.includes(": ") || v.length > 80) {
      return `${pad}|\n${v.split("\n").map((l) => `  ${pad}${l}`).join("\n")}`
    }
    return `${pad}${JSON.stringify(v)}`
  }
  if (typeof v === "number" || typeof v === "boolean") return `${pad}${v}`
  if (Array.isArray(v)) {
    if (v.length === 0) return `${pad}[]`
    return v.map((item) => `${pad}- ${yamlVal(item, indent + 1).trimStart()}`).join("\n")
  }
  if (typeof v === "object") {
    const keys = Object.keys(v as Record<string, unknown>)
    if (keys.length === 0) return `${pad}{}`
    return "\n" + keys
      .filter((k) => (v as Record<string, unknown>)[k] !== undefined)
      .map((k) => {
        const val = yamlVal((v as Record<string, unknown>)[k], indent + 1)
        if (val.startsWith("\n")) return `${pad}${k}:${val}`
        const first = val.slice(indent * 2 + 2)  // strip leading pad for inline
        return `${pad}${k}: ${first}`
      })
      .join("\n")
  }
  return `${pad}${v}`
}

function yamlDoc(obj: Record<string, unknown>): string {
  const parts: string[] = []
  for (const [k, v] of Object.entries(obj)) {
    const val = yamlVal(v, 0)
    if (val.startsWith("\n")) {
      parts.push(`${k}:${val}`)
    } else {
      parts.push(`${k}: ${val}`)
    }
  }
  return parts.join("\n")
}

// ---------------------------------------------------------------------------
// Turn data types
// ---------------------------------------------------------------------------

interface ToolCallPart {
  toolCallID: string
  toolName: string
  args?: string
  result?: string
  timestamp: string
}

interface TurnData {
  userText: string
  modelID: string | null
  thinking: string[]
  responseText: string[]
  toolCalls: ToolCallPart[]
  startTime: string
  endTime: string | null
}

function newTurn(): TurnData {
  return {
    userText: "",
    modelID: null,
    thinking: [],
    responseText: [],
    toolCalls: [],
    startTime: ts(),
    endTime: null,
  }
}

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

let currentSessionID: string | null = null
let sessionModel: string | null = null
let sessionCreated: string | null = null
let currentTurn: TurnData | null = null
let turnUserMessageID: string | null = null
let pendingToolCall: ToolCallPart | null = null

// ---------------------------------------------------------------------------
// Plugin
// ---------------------------------------------------------------------------

export const OpenCodeLogger: Plugin = async () => {
  return {
    event: async ({ event }) => {
      try {
        const p = (event as any).properties
        switch (event.type) {
          case "session.created": {
            const info = p?.info
            if (!info?.id) break
            currentSessionID = info.id
            sessionModel = info.modelID ?? info.model ?? null
            sessionCreated = ts()
            writeJSONL(info.id, {
              timestamp: sessionCreated,
              sessionID: info.id,
              type: "session.created",
              model: sessionModel,
            })
            break
          }

          case "message.updated": {
            const info = p?.info
            if (!info?.id) break
            const role = info.role
            const modelID = info.modelID ?? null
            if (role === "assistant" && modelID) {
              sessionModel = modelID
            }
            break
          }

          case "message.part.updated": {
            const part = p?.part
            if (!part?.messageID) break

            const msgProps = p?.message
            const role = msgProps?.role ?? "unknown"
            const sessionID = msgProps?.sessionID ?? currentSessionID
            if (!sessionID) break

            // Start a new turn on first user text part
            if (role === "user" && part.type === "text" && turnUserMessageID !== part.messageID) {
              if (currentTurn && currentTurn.endTime === null) {
                // Previous turn didn't complete — discard partial
              }
              currentTurn = newTurn()
              currentTurn.userText = part.text ?? ""
              currentTurn.modelID = sessionModel
              turnUserMessageID = part.messageID
            }

            const entry: Record<string, unknown> = {
              timestamp: ts(),
              sessionID,
              type: "message.part",
              role,
              partType: part.type,
              modelID: sessionModel,
              messageID: part.messageID,
            }

            switch (part.type) {
              case "text": {
                entry.text = part.text ?? ""
                if (currentTurn && role === "assistant") {
                  currentTurn.responseText.push(part.text ?? "")
                }
                break
              }
              case "reasoning": {
                entry.reasoning = part.text ?? part.reasoning ?? ""
                if (currentTurn && role === "assistant") {
                  currentTurn.thinking.push(part.text ?? part.reasoning ?? "")
                }
                break
              }
              case "tool_call": {
                entry.toolCallID = part.toolCallID ?? ""
                entry.toolName = part.toolName ?? ""
                entry.args = part.args ?? ""
                pendingToolCall = {
                  toolCallID: part.toolCallID ?? "",
                  toolName: part.toolName ?? "",
                  args: part.args ?? "",
                  timestamp: ts(),
                }
                break
              }
              case "tool_result": {
                entry.toolCallID = part.toolCallID ?? ""
                entry.result = part.data ?? part.text ?? ""
                if (pendingToolCall && pendingToolCall.toolCallID === part.toolCallID) {
                  pendingToolCall.result = part.data ?? part.text ?? ""
                  if (currentTurn) {
                    currentTurn.toolCalls.push({ ...pendingToolCall })
                  }
                  pendingToolCall = null
                }
                break
              }
              default:
                entry.text = part.text ?? ""
            }

            writeJSONL(sessionID, entry)
            break
          }

          case "session.status": {
            const sp = p?.properties ?? p
            if (sp?.status?.type !== "idle") break
            const sid = sp?.sessionID ?? currentSessionID
            if (!sid) break
            if (currentTurn) {
              currentTurn.endTime = ts()
            }
            writeJSONL(sid, {
              timestamp: ts(),
              sessionID: sid,
              type: "turn.complete",
            })
            break
          }

          case "session.compacted": {
            const sid = p?.sessionID ?? currentSessionID
            if (!sid) break
            writeJSONL(sid, {
              timestamp: ts(),
              sessionID: sid,
              type: "session.compacted",
            })
            break
          }

          case "session.deleted":
          case "server.instance.disposed": {
            const info = p?.info
            const sid = event.type === "session.deleted" ? (info?.id ?? currentSessionID) : currentSessionID
            if (!sid) break

            if (event.type === "session.deleted") {
              writeJSONL(sid, {
                timestamp: ts(),
                sessionID: sid,
                type: "session.deleted",
              })
            } else {
              writeJSONL(sid, {
                timestamp: ts(),
                sessionID: sid,
                type: "server.shutdown",
              })
            }

            // Write YAML summary
            writeYAMLSummary(sid)

            msgStore.clear()
            currentTurn = null
            turnUserMessageID = null
            if (currentSessionID === sid) currentSessionID = null
            break
          }
        }
      } catch {
        // Plugin failures must not crash OpenCode
      }
    },
  }
}

// ---------------------------------------------------------------------------
// State needed for YAML assembly
// ---------------------------------------------------------------------------

interface LogMsg {
  id: string
  role: string
  sessionID: string | null
  modelID: string | null
}

const msgStore = new Map<string, LogMsg>()

function ensureMsg(
  id: string, role: string, sessionID: string | null, modelID: string | null,
): LogMsg {
  let m = msgStore.get(id)
  if (!m) {
    m = { id, role, sessionID, modelID }
    msgStore.set(id, m)
  }
  if (modelID) m.modelID = modelID
  if (role !== "unknown") m.role = role
  return m
}

// ---------------------------------------------------------------------------
// YAML output
// ---------------------------------------------------------------------------

function writeYAMLSummary(sessionID: string) {
  try {
    mkdirSync(LOG_BASE, { recursive: true })
    const path = join(LOG_BASE, `${sessionID}.yaml`)
    const lines: string[] = []

    lines.push("---")
    lines.push(yamlDoc({
      session: {
        id: sessionID,
        created: sessionCreated,
      },
      model: sessionModel,
    }))

    const turn = currentTurn
    if (turn && turn.userText) {
      lines.push("---")
      const asst: Record<string, unknown> = {}
      if (turn.modelID) asst.model = turn.modelID
      if (turn.thinking.length > 0) asst.thinking = turn.thinking.join("")
      if (turn.responseText.length > 0) asst.response = turn.responseText.join("")
      if (turn.toolCalls.length > 0) {
        asst.tool_calls = turn.toolCalls.map((tc) => ({
          tool: tc.toolName,
          args: tc.args,
          result: tc.result,
        }))
      }
      if (turn.startTime && turn.endTime) {
        const ms = new Date(turn.endTime).getTime() - new Date(turn.startTime).getTime()
        asst.duration_ms = ms
      }
      const turnObj: Record<string, unknown> = {}
      turnObj.user = turn.userText
      turnObj.assistant = asst
      lines.push(yamlDoc(turnObj))
    }

    writeFileSync(path, lines.join("\n") + "\n")
  } catch {
    // Plugin failures must not crash OpenCode
  }
}
"}

